// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue } from '@skyramp/skyramp';
import { getLinksList, getUsersExport, postUsersExport, deleteUsersExport } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Step 1: accepted request against the replacement endpoint
    const linksGetResponse = await getLinksList(client, URL_localhost, headers, "0", 200);
    expect(getValue(linksGetResponse, "response"), 'links list is served, not an auth error').not.toBe("You must be logged in.");

    // Step 2: the removed export path answers 404
    const exportGetResponse = await getUsersExport(client, URL_localhost, headers, 404);
    expect(getValue(exportGetResponse, "response"), 'error body').toBe("Not found.");
    expect(getValue(exportGetResponse, "links"), 'no exported links payload').toBeNull();
    expect(getValue(exportGetResponse, "collections"), 'no exported collections payload').toBeNull();
    expect(getValue(exportGetResponse, "response.links"), 'no exported links payload nested under response').toBeNull();

    // Request Body
    const exportPostRequestBody: string = `{}`;

    // Step 3: a non-GET method on the removed path answers 404 too
    const exportPostResponse = await postUsersExport(client, URL_localhost, headers, exportPostRequestBody, 404);
    expect(getValue(exportPostResponse, "response"), 'error body').toBe("Not found.");
    expect(getValue(exportPostResponse, "links"), 'no exported links payload').toBeNull();
    expect(getValue(exportPostResponse, "collections"), 'no exported collections payload').toBeNull();

    // Step 4: a second non-GET method on the removed path answers 404 too
    const exportDeleteResponse = await deleteUsersExport(client, URL_localhost, headers, 404);
    expect(getValue(exportDeleteResponse, "response"), 'error body').toBe("Not found.");
    expect(getValue(exportDeleteResponse, "links"), 'no exported links payload').toBeNull();
    expect(getValue(exportDeleteResponse, "collections"), 'no exported collections payload').toBeNull();
});
